\begin{align*}
    \hat \aii_{\bm k}:=
    \begin{cases}
        \dfrac{1}{V}\,\dfrac{\hat M(\bm k)}{\hat\varphi(\bm k)^2}\,\hat \ai_{\bm k},
        & \bm k\in\mathcal{I}_{\bm{m}}\setminus\{\bm{0}\},\[2pt]
        0, & \bm k=\bm 0.
    \end{cases}
\end{align*}

